contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // Deploy a contract that always returns false on transferFrom
        RevertingReceiver receiver = new RevertingReceiver();

        // Prepare the call
        address[] memory tos = new address[](1);
        tos[0] = address(receiver);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;

        // Use the owner address to call transfer
        address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(owner);

        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference should revert (ok == false), buggy should pass (ok == true)
        // We assert true, but the divergence is that on the reference this assertion FAILS
        // (i.e., ok is false), while on the buggy version it FAILS (ok is true makes assertTrue(false)).
        // Actually we need the assertion to pass on reference and fail on buggy.
        // On reference: ok == false, so assertTrue(ok) fails. On buggy: ok == true, so assertTrue(ok) passes.
        // We want reference PASS, buggy FAIL. So we assert the opposite? 
        // Let's re-evaluate: the property is "after transfer, the reference reverts (ok false) and buggy returns true (ok true)".
        // A single assertion that holds on reference and breaks on buggy: assertTrue(!ok) would pass on reference (since !false = true) and fail on buggy (!true = false).
        assertTrue(!ok);
    }
}

contract RevertingReceiver {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
}

